={{(() => {
  const image = $binary.Product_Image;
  const userPrompt = $('When UGC Form Submitted').item.json['UGC Prompt'];

  return {
    model: 'openrouter/free',
    messages: [
      {
        role: 'user',
        content: [
          {
            type: 'text',
            text: `Analyze the attached product image for AI-generated UGC advertising.

Customer request:
${userPrompt}

Return JSON only with these fields:
product_type,
primary_color,
secondary_colors,
visible_material,
pattern,
visible_logo,
logo_text,
logo_position,
visible_text,
shape,
design_details,
distinguishing_features,
style,
key_features_that_must_not_change.

Describe only clearly visible details.
Do not invent hidden details.
Pay special attention to branding, logos, text, colors, patterns, proportions, stitching, collars, sleeves, closures, labels and graphics.`
          },
          {
            type: 'image_url',
            image_url: {
              url: `data:${image.mimeType};base64,${image.data}`
            }
          }
        ]
      }
    ]
  };
})()}}

