// Read the regenerated AI response
const raw = String($json.output ?? '');

// Remove optional Markdown code fences
const cleaned = raw
  .replace(/```json/gi, '')
  .replace(/```/g, '')
  .trim();

try {
  // Parse the AI response into clean fields
  const data = JSON.parse(cleaned);

  return {
    json: {
      image_prompt: data.image_prompt ?? '',
      video_prompt: data.video_prompt ?? '',
      negative_constraints: data.negative_constraints ?? '',
      regeneration_status: 'success'
    }
  };
} catch (error) {
  // Preserve the response if the model returned malformed JSON
  return {
    json: {
      image_prompt: cleaned,
      video_prompt: '',
      negative_constraints: '',
      regeneration_status: 'parse_failed',
      parse_error: error.message
    }
  };
}

// Get the AI Agent response
const raw = $json.output ?? '';

// Remove optional Markdown code fences
const cleaned = String(raw)
  .replace(/```json/gi, '')
  .replace(/```/g, '')
  .trim();

try {
  // Parse the JSON returned by the AI Agent
  const parsed = JSON.parse(cleaned);

  return {
    json: {
      image_prompt: parsed.image_prompt ?? '',
      video_prompt: parsed.video_prompt ?? '',
      negative_constraints: parsed.negative_constraints ?? '',
      parse_status: 'success'
    }
  };
} catch (error) {
  // Keep the raw response so you can debug malformed AI output
  return {
    json: {
      image_prompt: cleaned,
      video_prompt: '',
      negative_constraints: '',
      parse_status: 'fallback',
      parse_error: error.message
    }
  };
}

